/bin/zsh -lc "python3 -c \"from PIL import Image,ImageChops,ImageStat; import glob; fs=glob.glob('/tmp/chess_recon/warp1/*.jpg'); prev=None; ds=[]
for i,f in enumerate(fs):
 im=Image.open(f).convert('L').crop((20,20,492,492)).resize((64,64));
 if prev is not None: ds.append((i,ImageStat.Stat(ImageChops.difference(im,prev)).mean[0]));
 prev=im
print(' '.join(f'{i}:{v:.1f}' for i,v in ds if v>9))\""

